  /* ---------- router ---------- */
  function render() {
    var hash = location.hash || "#/";
    var seg = hash.replace(/^#\/?/, "").split("/");
    var route = seg[0] || "overview", view;
    if (route === "explorer") view = viewExplorer();
    else if (route === "experiment") view = viewDetail(decodeURIComponent(seg[1] || ""));
    else if (route === "about") view = viewAbout();
    else if (route === "compare") view = viewCompare(seg.slice(1).join("/"));
    else if (route === "investigations" && seg[1] === "compare") view = viewInvCompare(seg[2] || "");
    else if (route === "investigations") view = viewInvestigations(seg[1] || "");
    else if (route === "investigation") view = viewInvestigation(decodeURIComponent(seg[1] || ""));
    else if (route === "lab") view = viewLab();
    else if (route === "scenario") view = viewScenario(seg.slice(1).join("/"));
    else { route = "overview"; view = viewOverview(); }
    main.textContent = "";
    main.appendChild(view);
    var nav = route === "experiment" ? "explorer" : route === "investigation" ? "investigations" : route;
    Array.prototype.forEach.call(document.querySelectorAll("#nav a"), function (a) {
      if (a.getAttribute("data-route") === nav) a.setAttribute("aria-current", "page");
      else a.removeAttribute("aria-current");
    });
    window.scrollTo(0, 0);
  }
  window.addEventListener("hashchange", render);

  /* In-app links ("#/explorer", "#main") are handled here instead of by the browser's link
   * resolution. Hosted HTML previewers add a <base href> that makes a bare "#/explorer" resolve to
   * the raw file on GitHub (shown as unstyled text). Setting location.hash always uses the
   * document's own URL, so navigation stays on this page. Modified clicks fall through. */
  document.addEventListener("click", function (e) {
    if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    var a = e.target && e.target.closest ? e.target.closest("a[href]") : null;
    if (!a) return;
    var href = a.getAttribute("href");
    if (href === "#main") { e.preventDefault(); main.focus(); main.scrollIntoView(); return; }
    if (href.indexOf("#/") !== 0) return;
    e.preventDefault();
    if (location.hash === href) render(); else location.hash = href;
  });

  render();
